package com.archos.mediacenter.video.leanback;
import android.view.*;
import androidx.preference.PreferenceManager;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(application=com.archos.mediacenter.video.CustomApplication.class,sdk=28,qualifiers="w960dp-h540dp-land-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class NextQaWizardTest {
 @Before public void offline(){Shadows.shadowOf(RuntimeEnvironment.getApplication()).grantPermissions("app.supernova.player.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION");PreviewAsyncFixtures.offlineTransport();PreferenceManager.getDefaultSharedPreferences(RuntimeEnvironment.getApplication()).edit().putBoolean("try_new_ui",true).putBoolean("supernova_onboarding_complete",true).remove(CustomLibraryPage.KEY).commit();}
 @After public void drain() throws Exception {PreviewAsyncFixtures.drain();}
 @Test public void firstStepUpReachesNavigationAndReviewRightReachesSave() throws Exception {
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{View root=host.get().findViewById(android.R.id.content);PreviewPagesTest.layout(root);View first=root.findViewWithTag("wizard.step.0");assertNotNull(first);first.requestFocus();root.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_UP));assertSame(root.findViewWithTag("semantic:topnav.custom"),root.findFocus());View review=root.findViewWithTag("wizard.step.3");review.requestFocus();PreviewPagesTest.layout(root);review=root.findViewWithTag("wizard.step.3");review.requestFocus();root.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));assertSame(PreviewPagesTest.findText(root,"Save Page"),root.findFocus());PreviewPagesTest.capture(root,"next-qa-wizard-review-save");}finally{host.pause().stop().destroy();}
 }
 @Test public void dirtyExitStartsSafelyAndSaveShowsCustomLibraryWithEditAtRight() throws Exception {
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{View root=host.get().findViewById(android.R.id.content);PreviewPagesTest.layout(root);Object workspace=ReflectionHelpers.getField(host.get(),"workspace");CustomLibraryPage draft=ReflectionHelpers.getField(workspace,"draft");draft.name="QA Films";root.findViewWithTag("wizard.step.0").requestFocus();int[] exits={0};((PageExitGuard)workspace).requestExit(()->{exits[0]++;ReflectionHelpers.callInstanceMethod(workspace,"render");});android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();View decor=dialog.getWindow().getDecorView();assertSame(PreviewPagesTest.findText(decor,"Continue Editing"),decor.findFocus());PreviewPagesTest.findText(decor,"Save Page").performClick();PreviewPagesTest.layout(root);assertEquals(1,exits[0]);assertEquals("QA Films",CustomLibraryPage.load(host.get()).name);View edit=root.findViewWithTag("custom.control.edit");assertNotNull(edit);View filters=root.findViewWithTag("custom.control.filters");android.graphics.Rect editBounds=new android.graphics.Rect(),filterBounds=new android.graphics.Rect();assertTrue(edit.getGlobalVisibleRect(editBounds));assertTrue(filters.getGlobalVisibleRect(filterBounds));assertTrue(editBounds.left>filterBounds.right);assertNotNull(((android.widget.TextView)edit).getCompoundDrawables()[0]);}finally{host.pause().stop().destroy();}
 }
 @Test public void discardUsesRequestedDestinationAndInvalidSaveStaysInEditor() throws Exception {
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{
   Object workspace=ReflectionHelpers.getField(host.get(),"workspace");CustomLibraryPage draft=ReflectionHelpers.getField(workspace,"draft");draft.name="";int[] exits={0};
   ((PageExitGuard)workspace).requestExit(()->exits[0]++);View decor=org.robolectric.shadows.ShadowDialog.getLatestDialog().getWindow().getDecorView();PreviewPagesTest.findText(decor,"Save Page").performClick();assertEquals(0,exits[0]);assertTrue(ReflectionHelpers.getField(workspace,"editing"));assertNull(CustomLibraryPage.load(host.get()));
   org.robolectric.shadows.ShadowDialog.getLatestDialog().dismiss();((PageExitGuard)workspace).requestExit(()->exits[0]++);decor=org.robolectric.shadows.ShadowDialog.getLatestDialog().getWindow().getDecorView();PreviewPagesTest.findText(decor,"Discard Changes").performClick();assertEquals(1,exits[0]);assertNull(CustomLibraryPage.load(host.get()));CustomLibraryPage clean=ReflectionHelpers.getField(workspace,"draft");assertFalse(clean.name.isEmpty());assertEquals(ReflectionHelpers.getField(workspace,"original"),clean.encode());
  }finally{host.pause().stop().destroy();}
 }

 @Test public void previewFrameStaysOutsideScrollAndSemanticReturnSurvivesRebuild() throws Exception {
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{View root=host.get().findViewById(android.R.id.content);PreviewPagesTest.layout(root);Object workspace=ReflectionHelpers.getField(host.get(),"workspace");View name=root.findViewWithTag("wizard.option.0.Name");assertNotNull(name);name.requestFocus();root.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));View frame=root.findViewWithTag("wizard.preview");assertTrue(frame.hasFocus());assertNotNull(frame.getForeground());android.widget.ScrollView scroll=ReflectionHelpers.getField(workspace,"wizardPreview");assertSame(frame,((View)scroll.getParent()).getParent());assertNull(scroll.getForeground());
   ReflectionHelpers.callInstanceMethod(workspace,"render");PreviewPagesTest.layout(root);assertNotSame(name,root.findViewWithTag("wizard.option.0.Name"));root.findViewWithTag("wizard.preview").requestFocus();root.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_LEFT));assertSame(root.findViewWithTag("wizard.option.0.Name"),root.findFocus());
  }finally{host.pause().stop().destroy();}
 }

 @Test public void successfulEmptyTvPreviewDoesNotLabelItAsMovies(){
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{Object workspace=ReflectionHelpers.getField(host.get(),"workspace");CustomLibraryPage draft=ReflectionHelpers.getField(workspace,"draft");draft.type="tv";ReflectionHelpers.setField(host.get(),"snapshotLoading",false);ReflectionHelpers.setField(host.get(),"snapshotFailed",false);ReflectionHelpers.setField(workspace,"snapshot",new PreviewLibraryLoader.Snapshot());ReflectionHelpers.callInstanceMethod(workspace,"preview");android.widget.TextView preview=ReflectionHelpers.getField(workspace,"preview");assertTrue(preview.getText().toString().contains("0 Shows"));assertFalse(preview.getText().toString().contains("0 Movies"));assertTrue(preview.getText().toString().contains("No matching indexed items"));}finally{host.pause().stop().destroy();}
 }

 @Test public void draftChangesKeepShellAndPreviewUsesOnlyActualMatchingMedia()throws Exception{
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{View root=host.get().findViewById(android.R.id.content);PreviewPagesTest.layout(root);Object workspace=ReflectionHelpers.getField(host.get(),"workspace");CustomLibraryPage draft=ReflectionHelpers.getField(workspace,"draft");PreviewLibraryLoader.Snapshot snapshot=new PreviewLibraryLoader.Snapshot();com.archos.mediacenter.video.browser.adapters.object.Movie film=org.mockito.Mockito.mock(com.archos.mediacenter.video.browser.adapters.object.Movie.class);org.mockito.Mockito.when(film.getName()).thenReturn("Indexed movie");org.mockito.Mockito.when(film.getId()).thenReturn(1L);com.archos.mediacenter.video.browser.adapters.object.Tvshow show=org.mockito.Mockito.mock(com.archos.mediacenter.video.browser.adapters.object.Tvshow.class);org.mockito.Mockito.when(show.getName()).thenReturn("Indexed show");org.mockito.Mockito.when(show.getTvshowId()).thenReturn(2L);snapshot.movies.add(new PreviewLibraryLoader.Entry(film,0,0,""));snapshot.shows.add(new PreviewLibraryLoader.Entry(show,0,2,""));ReflectionHelpers.setField(workspace,"snapshot",snapshot);ReflectionHelpers.setField(host.get(),"snapshotLoading",false);View frame=root.findViewWithTag("wizard.preview");draft.type="movies";ReflectionHelpers.callInstanceMethod(workspace,"render");PreviewPagesTest.layout(root);assertSame(frame,root.findViewWithTag("wizard.preview"));assertNotNull(PreviewPagesTest.findText(frame,"Indexed movie"));assertNull(PreviewPagesTest.findText(frame,"Indexed show"));draft.type="tv";ReflectionHelpers.callInstanceMethod(workspace,"render");PreviewPagesTest.layout(root);assertSame(frame,root.findViewWithTag("wizard.preview"));assertNotNull(PreviewPagesTest.findText(frame,"Indexed show"));assertNull(PreviewPagesTest.findText(frame,"Indexed movie"));assertNotNull(root.findViewWithTag("wizard.option.0.TV Shows"));
  }finally{host.pause().stop().destroy();}
 }

 @Test public void oldFiveStepActivityStateRestoresItsEquivalentSection(){
  android.os.Bundle state=new android.os.Bundle();CustomLibraryPage page=new CustomLibraryPage();page.name="Retained draft";state.putString("draft",page.encode());state.putString("original",page.encode());state.putBoolean("editing",true);state.putInt("step",4);state.putString("focus","wizard.step.4");var host=Robolectric.buildActivity(CustomLibraryActivity.class).create(state).start().resume().visible();try{View root=host.get().findViewById(android.R.id.content);PreviewPagesTest.layout(root);assertNotNull(root.findViewWithTag("wizard.step.3"));assertNull(root.findViewWithTag("wizard.step.4"));assertTrue(root.findViewWithTag("wizard.step.3").hasFocus());assertNotNull(PreviewPagesTest.findText(root,"Save Page"));assertNotNull(PreviewPagesTest.findText(root,"Name: Retained draft"));}finally{host.pause().stop().destroy();}
 }

 @Test public void immediatePickerBackDoesNotReplayObsoleteChoiceFocus(){
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{View root=host.get().findViewById(android.R.id.content);PreviewPagesTest.layout(root);root.findViewWithTag("wizard.step.1").requestFocus();PreviewPagesTest.layout(root);View watched=root.findViewWithTag("wizard.option.1.Watched state");assertNotNull(watched);watched.requestFocus();watched.performClick();Object workspace=ReflectionHelpers.getField(host.get(),"workspace");ReflectionHelpers.callInstanceMethod(workspace,"back");PreviewPagesTest.layout(root);assertSame(root.findViewWithTag("wizard.option.1.Watched state"),root.findFocus());}
  finally{host.pause().stop().destroy();}
 }

 @Test public void retainedYearHasAVisibleCurrentMarkerAndPickerReturnsToItsParent(){
  var host=Robolectric.buildActivity(CustomLibraryActivity.class).setup().visible();try{View root=host.get().findViewById(android.R.id.content);PreviewPagesTest.layout(root);Object workspace=ReflectionHelpers.getField(host.get(),"workspace");CustomLibraryPage draft=ReflectionHelpers.getField(workspace,"draft");draft.year=1999;root.findViewWithTag("wizard.step.1").requestFocus();PreviewPagesTest.layout(root);View parent=root.findViewWithTag("wizard.option.1.Year");assertNotNull(parent);parent.requestFocus();parent.performClick();PreviewPagesTest.layout(root);android.widget.TextView current=root.findViewWithTag("wizard.option.1.1999");assertNotNull(current);assertTrue(current.isSelected());assertTrue(current.getText().toString().startsWith("✓"));assertTrue(current.hasFocus());assertFalse(root.findViewWithTag("wizard.option.1.All").isSelected());current.performClick();PreviewPagesTest.layout(root);assertEquals(1999,draft.year);assertSame(root.findViewWithTag("wizard.option.1.Year"),root.findFocus());}finally{host.pause().stop().destroy();}
 }

}
